SELECT COUNT(1) AS totalCase, ifnull(SUM(CASE WHEN status = 0 THEN 1 ELSE 0 END),0) AS pendAcceptCase, ifnull(SUM(CASE WHEN status = 1 THEN 1 ELSE 0 END),0) AS handlCase, ifnull(SUM(CASE WHEN status = 2 THEN 1 ELSE 0 END),0) AS completedCase, ifnull( SUM( CASE WHEN complete_time IS NOT NULL AND TIMESTAMPDIFF(SECOND, accept_time, complete_time) > #{prescribedDuration} * 24 * 3600 THEN 1 WHEN complete_time IS NULL AND TIMESTAMPDIFF(SECOND, accept_time, NOW()) > #{prescribedDuration} * 24 * 3600 THEN 1 ELSE 0 END ) ,0) AS overtimeCase, ROUND( ifnull( SUM(CASE WHEN status = 2 THEN 1 ELSE 0 END) / NULLIF(COUNT(1) - SUM(CASE WHEN status = 0 THEN 1 ELSE 0 END), 0) * 100 ,0 ) ,2 ) AS caseHandleRate FROM biz_case
AND status IN
#{status}
AND type = #{type}
and
